struct Aff:
    mul: Int
    add: Int

fn then(f: Aff, g: Aff) -> Aff:
    Aff(f.mul * g.mul, f.add * g.mul + g.add)

fn compose_all<D>(fs: [D]Aff) -> Aff:
    var acc = Aff(1, 0)
    for d in D:
        acc = then(acc, fs[d])
    acc

